keyframes:
@keyframes slideInRight { 
  0% { transform: translate3d(100%, 0px, 0px); visibility: visible; }
  100% { transform: translate3d(0px, 0px, 0px); }
}

@keyframes fadeInUp { 
  0% { opacity: 0; transform: translate3d(0px, 100%, 0px); }
  100% { opacity: 1; transform: none; }
}

@keyframes slideInDown { 
  0% { transform: translate3d(0px, -100%, 0px); visibility: visible; }
  100% { transform: translate3d(0px, 0px, 0px); }
}

@keyframes khDetailFade { 
  0% { opacity: 0; transform: translateY(3px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes khFlipNextCurtain { 
  0% { transform: perspective(1800px) rotateY(0deg) translateX(0px); }
  35% { transform: perspective(1800px) rotateY(-42deg) translateX(-3%); }
  70% { transform: perspective(1800px) rotateY(-82deg) translateX(-7%); }
  100% { transform: perspective(1800px) rotateY(-88deg) translateX(-10%); }
}

@keyframes khFlipPrevCurtain { 
  0% { transform: perspective(1800px) rotateY(0deg) translateX(0px); }
  35% { transform: perspective(1800px) rotateY(42deg) translateX(3%); }
  70% { transform: perspective(1800px) rotateY(82deg) translateX(7%); }
  100% { transform: perspective(1800px) rotateY(88deg) translateX(10%); }
}

@keyframes khFlipShadowNextCurtain { 
  0% { opacity: 0; transform: translateX(50%) scaleX(0.92); }
  35% { opacity: 0.08; transform: translateX(50%) scaleX(1); }
  70% { opacity: 0.14; transform: translateX(50%) scaleX(1.04); }
  100% { opacity: 0; transform: translateX(50%) scaleX(0.96); }
}

@keyframes khFlipShadowPrevCurtain { 
  0% { opacity: 0; transform: translateX(-50%) scaleX(0.92); }
  35% { opacity: 0.08; transform: translateX(-50%) scaleX(1); }
  70% { opacity: 0.14; transform: translateX(-50%) scaleX(1.04); }
  100% { opacity: 0; transform: translateX(-50%) scaleX(0.96); }
}
